namespace ws::log {
    enum class Level : uint8_t { Debug, Info, Warn, Error, Fatal };
    enum class AppenderType : uint8_t { StdOut, File };

    inline std::string_view LevelToString(Level level) noexcept {
        switch (level) {
            case Level::Debug: return "DEBUG";
            case Level::Info:  return "INFO ";
            case Level::Warn:  return "WARN ";
            case Level::Error: return "ERROR";
            case Level::Fatal: return "FATAL";
        }
        return "UNKNOWN";
    }

    inline std::string to_string(Level level) noexcept {
        return std::string{LevelToString(level)};
    }

    inline std::ostream& operator<<(std::ostream& os, Level level) noexcept {
        return os << LevelToString(level);
    }

    inline Level StringToLevel(std::string_view str) {
        if (str == "DEBUG"sv)  return Level::Debug;
        if (str == "INFO"sv)   return Level::Info;
        if (str == "WARN"sv)   return Level::Warn;
        if (str == "ERROR"sv)  return Level::Error;
        if (str == "FATAL"sv)  return Level::Fatal;
        throw std::invalid_argument{"Invalid log level: " + std::string{str}};
    }

    inline std::string_view AppenderTypeToString(AppenderType type) noexcept {
        switch (type) {
            case AppenderType::StdOut: return "stdout";
            case AppenderType::File:   return "file";
        }
        return "unknown";
    }

    inline std::string to_string(AppenderType type) noexcept {
        return std::string{AppenderTypeToString(type)};
    }

    inline std::ostream& operator<<(std::ostream& os, AppenderType type) noexcept {
        return os << AppenderTypeToString(type);
    }

    inline AppenderType StringToAppenderType(std::string_view str) {
        if (str == "stdout"sv) return AppenderType::StdOut;
        if (str == "file"sv)   return AppenderType::File;
        throw std::invalid_argument{"Invalid appender type: " + std::string{str}};
    }

    class Event {
    public:
        using Ptr = std::shared_ptr<Event>;
        using Clock = std::chrono::system_clock;

        static Ptr Create(Level level, 
                          std::experimental::source_location location = std::experimental::source_location::current(),
                          uint32_t thread_id = CurrentThreadId(),
                          Clock::time_point time = now()) noexcept {
            return std::make_shared<Event>(level, location, thread_id, time);
        }

        Event(Level level, 
              std::experimental::source_location location,
              uint32_t thread_id,
              Clock::time_point time) noexcept
            : level_{level},
              file_name_{location.file_name()},
              line_num_{static_cast<size_t>(location.line())},
              thread_id_{thread_id},
              time_{time} {}

        Level Level() const noexcept { return level_; }
        std::string_view FileName() const noexcept { return file_name_; }
        size_t LineNum() const noexcept { return line_num_; }
        uint32_t ThreadId() const noexcept { return thread_id_; }
        Clock::time_point Time() const noexcept { return time_; }

        std::string Message() const {
            if (msg_.tellp() == 0) return {};
            return msg_.str();
        }

        std::ostream& MessageStream() noexcept { return msg_; }

    private:
        Level level_;
        std::string_view file_name_;
        size_t line_num_;
        uint32_t thread_id_;
        Clock::time_point time_;
        std::ostringstream msg_;
    };

    inline std::ostream& operator<<(std::ostream& os, const Event& event) {
        return os << "[" << LevelToString(event.Level()) << "] "
                  << event.FileName() << ":" << event.LineNum() << " [" << event.ThreadId() << "] "
                  << event.Message();
    }

    class Formatter {
    public:
        using Ptr = std::shared_ptr<Formatter>;

        static Ptr Default() { return std::make_shared<Formatter>("[%l] %f:%L [%t] %m"); }

        explicit Formatter(std::string pattern) : pattern_{std::move(pattern)} {
            fields_ = ParsePattern(pattern_);
        }

        std::string Format(const Logger& logger, const Event& event) const noexcept;
        const std::string& Pattern() const noexcept { return pattern_; }

    private:
        std::string pattern_;
        std::list<std::shared_ptr<Field>> fields_;

        class Field {
        public:
            using Ptr = std::shared_ptr<Field>;
            explicit Field(std::string format) : format_{std::move(format)} {}
            virtual ~Field() = default;
            virtual void Format(std::ostream& out, const Logger& logger, const Event& event) const noexcept = 0;
            virtual std::string_view Tag() const noexcept = 0;

        protected:
            std::string format_;
        };
    };

    class Appender {
    public:
        using Ptr = std::shared_ptr<Appender>;

        explicit Appender(std::string pattern) : formatter_{Formatter::Default()} {}
        explicit Appender(Formatter::Ptr formatter) : formatter_{std::move(formatter)} {}
        virtual ~Appender() = default;

        virtual void Log(const Logger& logger, const Event& event) noexcept = 0;
        virtual std::string ToYamlString() const = 0;

        Formatter::Ptr GetFormatter() const noexcept { return formatter_; }
        void SetFormatter(Formatter::Ptr formatter) { formatter_ = std::move(formatter); }
        void SetFormatter(std::string pattern) { formatter_ = std::make_shared<Formatter>(std::move(pattern)); }

    protected:
        Formatter::Ptr formatter_;
        mutable std::mutex mtx_;
    };

    class StdOutAppender : public Appender {
    public:
        using Ptr = std::shared_ptr<StdOutAppender>;

        void Log(const Logger& logger, const Event& event) noexcept override {
            std::lock_guard lock{mtx_};
            auto out = std::ostringstream{};
            formatter_->Format(logger, event).swap().flush();
            std::osyncstream{std::cout} << out.str() << '\n';
        }

        std::string ToYamlString() const override {
            return "type: stdout\nformatter:\n  pattern: " + formatter_->Pattern() + "\n";
        }
    };

    class FileAppender : public Appender {
    public:
        using Ptr = std::shared_ptr<FileAppender>;

        explicit FileAppender(std::string file_name, Formatter::Ptr formatter = Formatter::Default())
            : file_name_{std::move(file_name)}, formatter_{std::move(formatter)} {
            file_.open(file_name_, std::ios::app);
            if (!file_) throw std::runtime_error{"Failed to open log file: " + file_name_};
        }

        void Log(const Logger& logger, const Event& event) noexcept override {
            std::lock_guard lock{mtx_};
            auto out = formatter_->Format(logger, event);
            file_ << out << '\n';
        }

        std::string ToYamlString() const override {
            return "type: file\nfile: " + file_name_ + "\nformatter:\n  pattern: " + formatter_->Pattern() + "\n";
        }

    private:
        std::string file_name_;
        std::ofstream file_;
    };

    class EventWriter {
    public:
        explicit EventWriter(Logger& logger, Event::Ptr event) noexcept : logger_{logger}, event_{std::move(event)} {}
        ~EventWriter() {
            if (event_) {
                std::ostringstream oss{};
                auto& stream = event_->MessageStream();
                stream << oss.str();
                logger_.Log(std::move(event_));
            }
        }

        std::ostream& MessageStream() noexcept { return event_->MessageStream(); }

    private:
        Logger& logger_;
        Event::Ptr event_;
    };

    class Logger {
    public:
        using Ptr = std::shared_ptr<Logger>;

        explicit Logger(std::string name, Level level = Level::Info, std::optional<size_t> capacity = std::nullopt)
            : name_{std::move(name)}, level_{level}, formatter_{Formatter::Default()},
              event_deque_{capacity ? std::make_unique<BlockDeque<Event::Ptr>>(*capacity) : nullptr} {}

        ~Logger() {
            if (async_) {
                async_ = false;
                writer_thread_->join();
            }
        }

        void Log(Event::Ptr event) noexcept {
            if (event->Level() < level_) return;
            if (async_) {
                std::lock_guard lock{mtx_};
                event_deque_->PushBack(std::move(event));
            } else {
                SyncLog(std::move(event));
            }
        }

        void AddAppender(Appender::Ptr appender) { appenders_.push_back(std::move(appender)); }
        bool RemoveAppender(const Appender& appender) {
            auto it = std::find_if(appenders_.begin(), appenders_.end(), [&](const auto& a){ return a.get() == &appender; });
            if (it != appenders_.end()) { appenders_.erase(it); return true; }
            return false;
        }
        void ClearAppenders() { appenders_.clear(); }

        Level GetLevel() const noexcept { return level_; }
        void SetLevel(Level level) { level_ = level; }

        Formatter::Ptr GetDefaultFormatter() const noexcept { return formatter_; }
        void SetFormatter(Formatter::Ptr formatter) { formatter_ = std::move(formatter); }
        void SetFormatter(std::string pattern) { formatter_ = std::make_shared<Formatter>(std::move(pattern)); }

        const std::string& Name() const noexcept { return name_; }
        size_t Capacity() const noexcept { return event_deque_ ? event_deque_->Capacity() : 0; }

        std::string ToYamlString() const {
            auto out = std::ostringstream{};
            out << "name: " << name_ << "\nlevel: " << LevelToString(level_) << "\nappenders:\n";
            for (const auto& appender : appenders_) out << "  - " << appender->ToYamlString() << "\n";
            return out.str();
        }

    private:
        std::string name_;
        size_t capacity_ = 0;
        Level level_;
        std::list<Appender::Ptr> appenders_;
        std::unique_ptr<BlockDeque<Event::Ptr>> event_deque_;
        Formatter::Ptr formatter_;
        mutable std::mutex mtx_;
        bool async_ = false;
        std::unique_ptr<std::thread> writer_thread_;

        void AsyncLogProc() noexcept {
            while (async_) {
                Event::Ptr event{};
                if (!event_deque_->TryPopFront(event)) continue;
                SyncLog(std::move(event));
            }
        }

        void SyncLog(Event::Ptr event) noexcept {
            std::lock_guard lock{mtx_};
            auto out = formatter_->Format(*this, *event);
            for (const auto& appender : appenders_) appender->Log(*this, *event);
        }
    };

    inline void Log(const Logger& logger, Event::Ptr event) { logger.Log(std::move(event)); }
    inline std::ostream& operator<<(std::ostream& os, const Logger& logger) {
        return os << "Logger: " << logger.Name() << " (Level: " << LevelToString(logger.GetLevel()) << ")";
    }

    class Manager {
    public:
        using Ptr = std::shared_ptr<Manager>;

        static void InitConfig() {}

        explicit Manager(std::string name) : name_{std::move(name)} {}

        const std::string& Name() const noexcept { return name_; }

        Logger::Ptr FindLogger(std::string_view name, Level level = Level::Info, std::optional<size_t> capacity = std::nullopt) {
            std::lock_guard lock{mtx_};
            auto it = loggers_.find(name);
            if (it != loggers_.end()) return it->second;
            auto logger = std::make_shared<Logger>(std::string{name}, level, capacity);
            loggers_[logger->Name()] = logger;
            return logger;
        }

        bool RemoveLogger(std::string_view name) {
            std::lock_guard lock{mtx_};
            auto it = loggers_.find(name);
            if (it != loggers_.end()) { loggers_.erase(it); return true; }
            return false;
        }

        std::string ToYamlString() const {
            auto out = std::ostringstream{};
            out << "name: " << name_ << "\nloggers:\n";
            for (const auto& [_, logger] : loggers_) out << "  - " << logger->ToYamlString() << "\n";
            return out.str();
        }

    private:
        std::string name_;
        std::unordered_map<std::string, Logger::Ptr> loggers_;
        mutable std::mutex mtx_;
    };

    inline Manager& RootManager() {
        static Manager manager{"root"};
        return manager;
    }

    inline Logger& RootLogger() { return *RootManager().FindLogger("root"); }

    inline Logger::Ptr FindLogger(std::string_view name, Level level = Level::Info, std::optional<size_t> capacity = std::nullopt) {
        return RootManager().FindLogger(name, level, capacity);
    }
}

