namespace ws::log::field {
    struct RawField {
        std::string tag;
        std::string format;

        bool operator==(const RawField& other) const noexcept {
            return tag == other.tag && format == other.format;
        }
        bool operator!=(const RawField& other) const noexcept { return !(*this == other); }
    };

    class Message : public Formatter::Field {
    public:
        void Format(std::ostream& out, const Logger& logger, const Event& event) const noexcept override {
            out << event.Message();
        }
        std::string_view Tag() const noexcept override { return "m"; }
    };

    class Level : public Formatter::Field {
    public:
        void Format(std::ostream& out, const Logger& logger, const Event& event) const noexcept override {
            out << ws::log::LevelToString(event.Level());
        }
        std::string_view Tag() const noexcept override { return "l"; }
    };

    class ThreadId : public Formatter::Field {
    public:
        void Format(std::ostream& out, const Logger& logger, const Event& event) const noexcept override {
            out << event.ThreadId();
        }
        std::string_view Tag() const noexcept override { return "t"; }
    };

    class DateTime : public Formatter::Field {
    public:
        explicit DateTime(std::string format) : Formatter::Field{std::move(format)} {}
        void Format(std::ostream& out, const Logger& logger, const Event& event) const noexcept override {
            auto time = std::chrono::system_clock::to_time_t(event.Time());
            auto tm = *std::localtime(&time);
            char buf[64];
            if (strftime(buf, sizeof(buf), format_.c_str(), &tm) == 0) {
                out << "????-??-?? ???:??:??";
            } else {
                out << buf;
            }
        }
        std::string_view Tag() const noexcept override { return "d"; }
    };

    class FileName : public Formatter::Field {
    public:
        void Format(std::ostream& out, const Logger& logger, const Event& event) const noexcept override {
            out << event.FileName();
        }
        std::string_view Tag() const noexcept override { return "f"; }
    };

    class LineNum : public Formatter::Field {
    public:
        void Format(std::ostream& out, const Logger& logger, const Event& event) const noexcept override {
            out << event.LineNum();
        }
        std::string_view Tag() const noexcept override { return "L"; }
    };

    class NewLine : public Formatter::Field {
    public:
        void Format(std::ostream& out, const Logger& logger, const Event& event) const noexcept override {
            out << '\n';
        }
        std::string_view Tag() const noexcept override { return "n"; }
    };

    class Tab : public Formatter::Field {
    public:
        void Format(std::ostream& out, const Logger& logger, const Event& event) const noexcept override {
            out << '\t';
        }
        std::string_view Tag() const noexcept override { return "T"; }
    };

    class RawString : public Formatter::Field {
    public:
        explicit RawString(std::string format) : Formatter::Field{std::move(format)} {}
        void Format(std::ostream& out, const Logger& logger, const Event& event) const noexcept override {
            out << format_;
        }
        std::string_view Tag() const noexcept override { return "%"; }
    };

    class LoggerName : public Formatter::Field {
    public:
        void Format(std::ostream& out, const Logger& logger, const Event& event) const noexcept override {
            out << logger.Name();
        }
        std::string_view Tag() const noexcept override { return "N"; }
    };

    std::list<RawField> ParsePattern(std::string_view pattern);
    std::list<std::shared_ptr<Formatter::Field>> RawFieldsToFormatFields(const std::list<RawField>& raw_fields);
}

#include "field.h"
#include <ctime>
#include <functional>
#include <stdexcept>
#include <unordered_map>

namespace ws::log::field {
    std::list<RawField> ParsePattern(std::string_view pattern) {
        auto fields = std::list<RawField>{};
        size_t pos = 0;
        while (pos < pattern.size()) {
            if (pattern[pos] == '%') {
                if (pos + 1 >= pattern.size()) throw std::invalid_argument{"Invalid format: %% at end"};
                auto tag = pattern[++pos];
                auto format_start = pos + 1;
                while (pos < pattern.size() && pattern[pos] != '%') ++pos;
                auto format_end = pos;
                if (tag == 'd' || tag == '%' || tag == 'N') {
                    fields.push_back({std::string{1, tag}, std::string{pattern.substr(format_start, format_end - format_start)}});
                } else {
                    fields.push_back({std::string{1, tag}, {}});
                }
            } else if (pattern[pos] == '\\') {
                if (pos + 1 >= pattern.size()) throw std::invalid_argument{"Invalid escape sequence"};
                auto c = pattern[++pos];
                fields.push_back({"%", std::string{1, c}});
            } else {
                fields.push_back({"%", std::string{1, pattern[pos]}});
            }
            ++pos;
        }
        return fields;
    }

    std::list<std::shared_ptr<Formatter::Field>> RawFieldsToFormatFields(const std::list<RawField>& raw_fields) {
        static const auto creators = std::unordered_map<std::string, std::function<std::shared_ptr<Formatter::Field>(const RawField&)>>{
            {"m", [](const auto& f){ return std::make_shared<Message>(); }},
            {"l", [](const auto& f){ return std::make_shared<Level>(); }},
            {"t", [](const auto& f){ return std::make_shared<ThreadId>(); }},
            {"d", [](const auto& f){ return std::make_shared<DateTime>(f.format); }},
            {"f", [](const auto& f){ return std::make_shared<FileName>(); }},
            {"L", [](const auto& f){ return std::make_shared<LineNum>(); }},
            {"n", [](const auto& f){ return std::make_shared<NewLine>(); }},
            {"T", [](const auto& f){ return std::make_shared<Tab>(); }},
            {"%", [](const auto& f){ return std::make_shared<RawString>(f.format); }},
            {"N", [](const auto& f){ return std::make_shared<LoggerName>(); }}
        };

        auto fields = std::list<std::shared_ptr<Formatter::Field>>{};
        for (const auto& raw : raw_fields) {
            auto it = creators.find(raw.tag);
            if (it == creators.end()) throw std::invalid_argument{"Unknown field tag: " + raw.tag};
            fields.push_back(it->second(raw));
        }
        return fields;
    }
}

