    struct AppenderConfig {
        std::string type;
        std::optional<std::string> file;
        std::string pattern;

        bool operator==(const AppenderConfig& other) const noexcept {
            return type == other.type && file == other.file && pattern == other.pattern;
        }
        bool operator!=(const AppenderConfig& other) const noexcept { return !(*this == other); }
    };

    struct LoggerConfig {
        std::string name;
        Level level = Level::Info;
        std::vector<AppenderConfig> appenders;

        bool operator==(const LoggerConfig& other) const noexcept {
            return name == other.name && level == other.level && appenders == other.appenders;
        }
        bool operator!=(const LoggerConfig& other) const noexcept { return !(*this == other); }
    };

    void SetListener(std::function<void(const LoggerConfig&)> listener);
}

